package com.ribaut.watchdesigner;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.*;
import android.net.Uri;
import android.os.BatteryManager;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.InputStream;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    private static final int PICK_BG=101,PICK_HOUR=201,PICK_MINUTE=202,PICK_SECOND=203;
    private static final int[] HAND_COLORS={Color.WHITE,Color.rgb(255,120,40),Color.RED,Color.CYAN,Color.rgb(120,255,120)};
    private static final int[] TEXT_COLORS={Color.WHITE,Color.LTGRAY,Color.rgb(255,180,50),Color.CYAN,Color.GREEN};
    private static final int[] BG_COLORS={Color.BLACK,Color.rgb(24,24,30),Color.rgb(20,35,48),Color.rgb(48,24,24),Color.rgb(25,45,28)};
    private static final String[] FONTS={"Classique","Gras","Fin","Monospace","Serif"};
    private SharedPreferences prefs; private WatchPreview preview;
    private SeekBar bgSeek,handSeek,infoSeek,hourSize,minuteSize,secondSize,hourPivot,minutePivot,secondPivot;
    private CheckBox secondsBox,dateBox,batteryBox,smallDigitalBox;
    private Spinner modeSpinner,digitalFontSpinner,dateFontSpinner; private Button activeBtn,standbyBtn,handColorBtn,textColorBtn,bgColorBtn;
    private boolean standby=false,loading=false; private int handColorIndex=0,textColorIndex=0,bgColorIndex=0;

    @Override protected void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("ribaut_watch_designer",MODE_PRIVATE);
        ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(12),dp(14),dp(24));root.setBackgroundColor(Color.rgb(18,18,22));scroll.addView(root);
        TextView title=text("Ribaut Watch Designer V2",22,true);title.setGravity(Gravity.CENTER);root.addView(title,matchWrap());
        preview=new WatchPreview(this);root.addView(preview,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(320)));
        LinearLayout pr=horizontal();activeBtn=button("ACTIF");standbyBtn=button("VEILLE");pr.addView(activeBtn,weighted());pr.addView(standbyBtn,weighted());root.addView(pr,matchWrap());activeBtn.setOnClickListener(v->switchProfile(false));standbyBtn.setOnClickListener(v->switchProfile(true));
        root.addView(section("Type de cadran"));modeSpinner=spinner(new String[]{"Analogique","Numérique"});root.addView(modeSpinner,matchWrap());smallDigitalBox=check("Ajouter une petite heure numérique sur le cadran analogique");root.addView(smallDigitalBox,matchWrap());
        root.addView(section("Police de l'heure numérique"));digitalFontSpinner=spinner(FONTS);root.addView(digitalFontSpinner,matchWrap());root.addView(section("Police de la date"));dateFontSpinner=spinner(FONTS);root.addView(dateFontSpinner,matchWrap());
        root.addView(section("Photo de fond"));Button photoBtn=button("Choisir la photo de fond du mode sélectionné");root.addView(photoBtn,matchWrap());photoBtn.setOnClickListener(v->chooseImage(PICK_BG));Button copyPhotoBtn=button("Copier la photo ACTIF vers VEILLE");root.addView(copyPhotoBtn,matchWrap());copyPhotoBtn.setOnClickListener(v->copyActivePhotoToStandby());
        root.addView(section("Aiguilles personnalisées (PNG transparent conseillé)"));
        LinearLayout hr=horizontal();Button h=button("Image HEURES"),m=button("Image MINUTES"),s=button("Image SECONDES");hr.addView(h,weighted());hr.addView(m,weighted());hr.addView(s,weighted());root.addView(hr,matchWrap());h.setOnClickListener(v->chooseImage(PICK_HOUR));m.setOnClickListener(v->chooseImage(PICK_MINUTE));s.setOnClickListener(v->chooseImage(PICK_SECOND));
        hourSize=addSlider(root,"Taille aiguille heures",150);minuteSize=addSlider(root,"Taille aiguille minutes",150);secondSize=addSlider(root,"Taille aiguille secondes",150);hourPivot=addSlider(root,"Pivot heures",100);minutePivot=addSlider(root,"Pivot minutes",100);secondPivot=addSlider(root,"Pivot secondes",100);
        Button clearHands=button("Retirer les images d'aiguilles du mode sélectionné");root.addView(clearHands,matchWrap());clearHands.setOnClickListener(v->{String x=suffix();prefs.edit().remove("hour_uri"+x).remove("minute_uri"+x).remove("second_uri"+x).apply();loadHandImages();});
        root.addView(section("Apparence du mode sélectionné"));bgSeek=addSlider(root,"Éclairage visuel du fond",100);handSeek=addSlider(root,"Éclairage des aiguilles / chiffres",100);infoSeek=addSlider(root,"Éclairage texte / informations",100);
        secondsBox=check("Afficher les secondes");dateBox=check("Afficher la date (lun, mar, mer…)");batteryBox=check("Afficher la batterie");root.addView(secondsBox,matchWrap());root.addView(dateBox,matchWrap());root.addView(batteryBox,matchWrap());
        LinearLayout cr=horizontal();bgColorBtn=button("Fond");handColorBtn=button("Aiguilles");cr.addView(bgColorBtn,weighted());cr.addView(handColorBtn,weighted());root.addView(cr,matchWrap());textColorBtn=button("Couleur du texte");root.addView(textColorBtn,matchWrap());
        bgColorBtn.setOnClickListener(v->{bgColorIndex=(bgColorIndex+1)%BG_COLORS.length;saveProfile();apply();colors();});handColorBtn.setOnClickListener(v->{handColorIndex=(handColorIndex+1)%HAND_COLORS.length;saveProfile();apply();colors();});textColorBtn.setOnClickListener(v->{textColorIndex=(textColorIndex+1)%TEXT_COLORS.length;saveProfile();apply();colors();});
        SeekBar.OnSeekBarChangeListener sl=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){if(!loading)apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){saveProfile();}};for(SeekBar b:new SeekBar[]{bgSeek,handSeek,infoSeek,hourSize,minuteSize,secondSize,hourPivot,minutePivot,secondPivot})b.setOnSeekBarChangeListener(sl);
        View.OnClickListener ol=v->{saveProfile();apply();};secondsBox.setOnClickListener(ol);dateBox.setOnClickListener(ol);batteryBox.setOnClickListener(ol);smallDigitalBox.setOnClickListener(ol);
        AdapterView.OnItemSelectedListener il=new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(!loading){saveProfile();apply();}}public void onNothingSelected(AdapterView<?> p){}};modeSpinner.setOnItemSelectedListener(il);digitalFontSpinner.setOnItemSelectedListener(il);dateFontSpinner.setOnItemSelectedListener(il);
        LinearLayout ar=horizontal();Button save=button("ENREGISTRER"),reset=button("RÉINITIALISER");ar.addView(save,weighted());ar.addView(reset,weighted());root.addView(ar,matchWrap());save.setOnClickListener(v->{saveProfile();Toast.makeText(this,"Projet enregistré",Toast.LENGTH_SHORT).show();});reset.setOnClickListener(v->reset());
        Button install=button("INSTALLER SUR LA WATCH 8");root.addView(install,matchWrap());install.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Installation Watch 8").setMessage("La liaison d'installation vers la montre est en cours d'intégration sur cette branche de test.").setPositiveButton("OK",null).show());setContentView(scroll);loadProfile();}

    private Spinner spinner(String[] v){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,v));return s;}
    private void chooseImage(int code){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,code);}
    @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null||d.getData()==null)return;Uri u=d.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}String k=r==PICK_BG?"background_uri":r==PICK_HOUR?"hour_uri":r==PICK_MINUTE?"minute_uri":r==PICK_SECOND?"second_uri":null;if(k!=null){prefs.edit().putString(k+suffix(),u.toString()).apply();if(r==PICK_BG)loadProfileImage();else loadHandImages();}}
    private void copyActivePhotoToStandby(){String u=prefs.getString("background_uri_a",null);if(u==null){Toast.makeText(this,"Aucune photo ACTIF à copier",Toast.LENGTH_SHORT).show();return;}prefs.edit().putString("background_uri_s",u).apply();if(standby)loadProfileImage();Toast.makeText(this,"Photo ACTIF copiée vers VEILLE",Toast.LENGTH_SHORT).show();}
    private String suffix(){return standby?"_s":"_a";}private void switchProfile(boolean s){if(standby==s)return;saveProfile();standby=s;loadProfile();}
    private void loadProfile(){loading=true;String s=suffix();bgSeek.setProgress(prefs.getInt("bg"+s,standby?10:80));handSeek.setProgress(prefs.getInt("hands"+s,standby?40:100));infoSeek.setProgress(prefs.getInt("info"+s,standby?45:100));hourSize.setProgress(prefs.getInt("hourSize"+s,70));minuteSize.setProgress(prefs.getInt("minuteSize"+s,90));secondSize.setProgress(prefs.getInt("secondSize"+s,100));hourPivot.setProgress(prefs.getInt("hourPivot"+s,15));minutePivot.setProgress(prefs.getInt("minutePivot"+s,12));secondPivot.setProgress(prefs.getInt("secondPivot"+s,10));secondsBox.setChecked(prefs.getBoolean("seconds"+s,!standby));dateBox.setChecked(prefs.getBoolean("date"+s,true));batteryBox.setChecked(prefs.getBoolean("battery"+s,true));smallDigitalBox.setChecked(prefs.getBoolean("smallDigital"+s,false));modeSpinner.setSelection(prefs.getInt("mode"+s,0));digitalFontSpinner.setSelection(prefs.getInt("digitalFont"+s,1));dateFontSpinner.setSelection(prefs.getInt("dateFont"+s,0));bgColorIndex=prefs.getInt("bgColor"+s,0)%BG_COLORS.length;handColorIndex=prefs.getInt("handColor"+s,0)%HAND_COLORS.length;textColorIndex=prefs.getInt("textColor"+s,0)%TEXT_COLORS.length;loading=false;activeBtn.setEnabled(standby);standbyBtn.setEnabled(!standby);colors();loadProfileImage();loadHandImages();apply();}
    private void loadProfileImage(){preview.clearBackground();String u=prefs.getString("background_uri"+suffix(),null);if(u==null&&!standby)u=prefs.getString("background_uri",null);if(u!=null)preview.loadBackground(Uri.parse(u));}
    private void loadHandImages(){preview.clearHands();String s=suffix();preview.loadHand(0,uri("hour_uri"+s));preview.loadHand(1,uri("minute_uri"+s));preview.loadHand(2,uri("second_uri"+s));}
    private Uri uri(String k){String u=prefs.getString(k,null);return u==null?null:Uri.parse(u);}
    private void saveProfile(){if(loading||bgSeek==null)return;String s=suffix();prefs.edit().putInt("bg"+s,bgSeek.getProgress()).putInt("hands"+s,handSeek.getProgress()).putInt("info"+s,infoSeek.getProgress()).putInt("hourSize"+s,hourSize.getProgress()).putInt("minuteSize"+s,minuteSize.getProgress()).putInt("secondSize"+s,secondSize.getProgress()).putInt("hourPivot"+s,hourPivot.getProgress()).putInt("minutePivot"+s,minutePivot.getProgress()).putInt("secondPivot"+s,secondPivot.getProgress()).putBoolean("seconds"+s,secondsBox.isChecked()).putBoolean("date"+s,dateBox.isChecked()).putBoolean("battery"+s,batteryBox.isChecked()).putBoolean("smallDigital"+s,smallDigitalBox.isChecked()).putInt("mode"+s,modeSpinner.getSelectedItemPosition()).putInt("digitalFont"+s,digitalFontSpinner.getSelectedItemPosition()).putInt("dateFont"+s,dateFontSpinner.getSelectedItemPosition()).putInt("bgColor"+s,bgColorIndex).putInt("handColor"+s,handColorIndex).putInt("textColor"+s,textColorIndex).apply();}
    private void reset(){String s=suffix();SharedPreferences.Editor e=prefs.edit();String[] k={"bg","hands","info","seconds","date","battery","smallDigital","mode","digitalFont","dateFont","bgColor","handColor","textColor","background_uri","hour_uri","minute_uri","second_uri","hourSize","minuteSize","secondSize","hourPivot","minutePivot","secondPivot"};for(String x:k)e.remove(x+s);e.apply();loadProfile();}
    private void apply(){if(preview==null||bgSeek==null)return;preview.digital=modeSpinner.getSelectedItemPosition()==1;preview.smallDigital=smallDigitalBox.isChecked();preview.showSeconds=secondsBox.isChecked();preview.showDate=dateBox.isChecked();preview.showBattery=batteryBox.isChecked();preview.bgPercent=bgSeek.getProgress();preview.handPercent=handSeek.getProgress();preview.infoPercent=infoSeek.getProgress();preview.bgColor=BG_COLORS[bgColorIndex];preview.handColor=HAND_COLORS[handColorIndex];preview.textColor=TEXT_COLORS[textColorIndex];preview.digitalFont=digitalFontSpinner.getSelectedItemPosition();preview.dateFont=dateFontSpinner.getSelectedItemPosition();preview.handScale[0]=Math.max(.2f,hourSize.getProgress()/100f);preview.handScale[1]=Math.max(.2f,minuteSize.getProgress()/100f);preview.handScale[2]=Math.max(.2f,secondSize.getProgress()/100f);preview.handPivot[0]=hourPivot.getProgress()/100f;preview.handPivot[1]=minutePivot.getProgress()/100f;preview.handPivot[2]=secondPivot.getProgress()/100f;preview.invalidate();}
    private void colors(){bgColorBtn.setTextColor(BG_COLORS[bgColorIndex]);handColorBtn.setTextColor(HAND_COLORS[handColorIndex]);textColorBtn.setTextColor(TEXT_COLORS[textColorIndex]);}
    private SeekBar addSlider(LinearLayout r,String l,int max){TextView t=text(l,14,false);t.setTextColor(Color.LTGRAY);r.addView(t,matchWrap());SeekBar b=new SeekBar(this);b.setMax(max);r.addView(b,matchWrap());return b;}
    private TextView section(String s){return text(s,16,true);}private TextView text(String s,int sp,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(Color.WHITE);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}private CheckBox check(String s){CheckBox c=new CheckBox(this);c.setText(s);c.setTextColor(Color.WHITE);return c;}private LinearLayout horizontal(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER);return l;}private LinearLayout.LayoutParams weighted(){return new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f);}private LinearLayout.LayoutParams matchWrap(){return new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}

    public static class WatchPreview extends View{
        private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private Bitmap background;private final Bitmap[] hands=new Bitmap[3];final float[] handScale={.7f,.9f,1f},handPivot={.15f,.12f,.1f};boolean digital,smallDigital,showSeconds=true,showDate=true,showBattery=true;int bgPercent=80,handPercent=100,infoPercent=100,bgColor=Color.BLACK,handColor=Color.WHITE,textColor=Color.WHITE,digitalFont=1,dateFont=0;
        WatchPreview(MainActivity c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);post(tick);}
        private final Runnable tick=new Runnable(){public void run(){invalidate();postDelayed(this,1000);}};
        void clearBackground(){background=null;invalidate();}void loadBackground(Uri u){background=decode(u);invalidate();}void clearHands(){Arrays.fill(hands,null);invalidate();}void loadHand(int i,Uri u){if(u!=null)hands[i]=decode(u);invalidate();}
        private Bitmap decode(Uri u){try(InputStream in=getContext().getContentResolver().openInputStream(u)){return BitmapFactory.decodeStream(in);}catch(Exception e){return null;}}
        private Typeface font(int i){switch(i){case 1:return Typeface.DEFAULT_BOLD;case 2:return Typeface.create("sans-serif-light",Typeface.NORMAL);case 3:return Typeface.MONOSPACE;case 4:return Typeface.SERIF;default:return Typeface.DEFAULT;}}
        @Override protected void onDraw(Canvas c){super.onDraw(c);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())/2f-10;Path clip=new Path();clip.addCircle(cx,cy,r,Path.Direction.CW);c.save();c.clipPath(clip);p.setStyle(Paint.Style.FILL);p.setColor(Color.BLACK);p.setAlpha(255);c.drawCircle(cx,cy,r,p);if(background!=null)drawBackground(c,cx-r,cy-r,cx+r,cy+r);else{p.setColor(bgColor);p.setAlpha(alpha(bgPercent));c.drawCircle(cx,cy,r,p);}Date now=new Date();if(digital)drawDigital(c,cx,cy,r,now,false);else{drawAnalog(c,cx,cy,r);if(smallDigital)drawDigital(c,cx,cy+r*.42f,r,now,true);}drawInfo(c,cx,cy,r,now);c.restore();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);p.setColor(Color.DKGRAY);p.setAlpha(255);c.drawCircle(cx,cy,r,p);}
        private void drawAnalog(Canvas c,float cx,float cy,float r){Calendar cal=Calendar.getInstance();int h=cal.get(Calendar.HOUR),m=cal.get(Calendar.MINUTE),s=cal.get(Calendar.SECOND);for(int i=0;i<12;i++){double a=Math.toRadians(i*30-90);p.setColor(handColor);p.setAlpha(alpha(handPercent));p.setStrokeWidth(i%3==0?5:3);c.drawLine(cx+(float)Math.cos(a)*r*.78f,cy+(float)Math.sin(a)*r*.78f,cx+(float)Math.cos(a)*r*.87f,cy+(float)Math.sin(a)*r*.87f,p);}drawHand(c,0,cx,cy,r*.48f,(h+m/60f)*30,9);drawHand(c,1,cx,cy,r*.68f,m*6,6);if(showSeconds)drawHand(c,2,cx,cy,r*.74f,s*6,2.5f);}
        private void drawHand(Canvas c,int i,float cx,float cy,float len,float clockDeg,float w){Bitmap b=hands[i];if(b==null){double a=Math.toRadians(clockDeg-90);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(w);p.setColor(handColor);p.setAlpha(alpha(handPercent));c.drawLine(cx,cy,cx+(float)Math.cos(a)*len,cy+(float)Math.sin(a)*len,p);return;}float target=len*handScale[i],sc=target/Math.max(1,b.getHeight()),dw=b.getWidth()*sc,dh=b.getHeight()*sc,pivotY=dh*(1f-handPivot[i]);c.save();c.rotate(clockDeg,cx,cy);p.setAlpha(alpha(handPercent));c.drawBitmap(b,null,new RectF(cx-dw/2,cy-pivotY,cx+dw/2,cy+(dh-pivotY)),p);c.restore();}
        private void drawDigital(Canvas c,float cx,float cy,float r,Date d,boolean small){String pat=showSeconds&&!small?"HH:mm:ss":"HH:mm";p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(handColor);p.setAlpha(alpha(handPercent));p.setTypeface(font(digitalFont));p.setTextSize(r*(small?.16f:(showSeconds?.28f:.34f)));c.drawText(new SimpleDateFormat(pat,Locale.FRANCE).format(d),cx,cy,p);}
        private void drawInfo(Canvas c,float cx,float cy,float r,Date d){p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(textColor);p.setAlpha(alpha(infoPercent));if(showDate){p.setTypeface(font(dateFont));p.setTextSize(r*.105f);String v=new SimpleDateFormat("EEE dd MMM",Locale.FRANCE).format(d).replace(".","").toLowerCase(Locale.FRANCE);c.drawText(v,cx,cy+r*.58f,p);}if(showBattery){BatteryManager bm=(BatteryManager)getContext().getSystemService(BATTERY_SERVICE);int n=bm!=null?bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY):-1;p.setTypeface(Typeface.DEFAULT);p.setTextSize(r*.095f);c.drawText(n>=0?"Batterie "+n+"%":"Batterie --%",cx,cy+r*.73f,p);}}
        private void drawBackground(Canvas c,float l,float t,float rr,float b){float dw=rr-l,dh=b-t,sc=Math.max(dw/background.getWidth(),dh/background.getHeight());int sw=Math.max(1,Math.round(dw/sc)),sh=Math.max(1,Math.round(dh/sc)),sx=Math.max(0,(background.getWidth()-sw)/2),sy=Math.max(0,(background.getHeight()-sh)/2);p.setAlpha(alpha(bgPercent));c.drawBitmap(background,new Rect(sx,sy,Math.min(background.getWidth(),sx+sw),Math.min(background.getHeight(),sy+sh)),new RectF(l,t,rr,b),p);p.setAlpha(255);}private int alpha(int x){return Math.max(0,Math.min(255,Math.round(x*2.55f)));}
    }
}
